import fs from "node:fs";
import path from "node:path";
import { logger } from "~/utils/logger";

/** Generated by `pnpm run i18n:usage` as part of the build */
const USAGE_INDEX_PATH = path.join(process.cwd(), "translation-usage.json");

type UsageIndex = {
	routes: string[];
	files: string[];
	keys: Record<string, { f: number[]; r: number[]; s?: 1 }>;
};

export type TranslationUsage = {
	/** Used by a component rendered on every page e.g. the navigation */
	isSiteWide: boolean;
	/** Route paths e.g. `/u/:identifier/builds` */
	routes: string[];
	/** Source files relative to the repository root */
	files: string[];
};

let index: UsageIndex | null = null;

/** Where in the codebase the translation unit is used, `null` if it could not be determined (e.g. dynamically built key) */
export function forUnit({
	namespace,
	id,
}: {
	namespace: string;
	id: string;
}): TranslationUsage | null {
	const usageIndex = loadIndex();
	const entry =
		usageIndex.keys[`${namespace}:${id}`] ??
		usageIndex.keys[`${namespace}:${id.replace(/_zero$/, "")}`];
	if (!entry) return null;

	return {
		isSiteWide: entry.s === 1,
		routes: entry.r.map((idx) => usageIndex.routes[idx]),
		files: entry.f.map((idx) => usageIndex.files[idx]),
	};
}

function loadIndex(): UsageIndex {
	index ??= readIndex();
	return index;
}

function readIndex(): UsageIndex {
	try {
		return JSON.parse(fs.readFileSync(USAGE_INDEX_PATH, "utf8"));
	} catch (err) {
		logger.warn(
			`Could not read the translation usage index, run "pnpm run i18n:usage" to generate it: ${(err as Error).message}`,
		);
		return { routes: [], files: [], keys: {} };
	}
}
